// Always emit {access_token, refresh_token, token_expires}. Refresh from
// Etsy when the token expires within 60s; otherwise pass through unchanged.
const row = $input.first().json;
if (!row || !row.listing_id) throw new Error('Listing not found');
if (!row.etsy_shop_id || !row.oauth_token) {
  throw new Error(`Shop ${row.shop_pk} is not connected to Etsy. Run /webhook/etsy-connect first.`);
}

const expiresAtMs = row.token_expires ? new Date(row.token_expires).getTime() : 0;
const needsRefresh = expiresAtMs - Date.now() < 60_000;

if (!needsRefresh) {
  return [{ json: {
    ...row,
    access_token:  row.oauth_token,
    refresh_token: row.refresh_token,
    token_expires: row.token_expires,
    refreshed: false
  } }];
}

const params = new URLSearchParams({
  grant_type:    'refresh_token',
  client_id:     process.env.ETSY_CLIENT_ID,
  refresh_token: row.refresh_token
}).toString();

const tok = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.etsy.com/v3/public/oauth/token',
  headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
  body: params,
  json: true,
  timeout: 30000
});
if (!tok.access_token) throw new Error(`Token refresh failed: ${JSON.stringify(tok)}`);

return [{ json: {
  ...row,
  access_token:  tok.access_token,
  refresh_token: tok.refresh_token,
  token_expires: new Date(Date.now() + (tok.expires_in - 60) * 1000).toISOString(),
  refreshed: true
} }];

// Build the Etsy createDraftListing payload. Defaults are conservative:
// listings are created in 'draft' state for review; for printables they're
// digital/instant downloads; for POD they're physical with quantity=999.
const row = $('Refresh If Needed').first().json;
const tags = Array.isArray(row.tags) ? row.tags.slice(0, 13) : [];
const isDigital = row.kind === 'printable';

const payload = {
  quantity:         isDigital ? 999 : 1,
  title:            row.title,
  description:      row.description,
  price:            Number(row.price),
  who_made:         'i_did',
  when_made:        'made_to_order',
  taxonomy_id:      6884,
  type:             isDigital ? 'download'  : 'physical',
  state:            'draft',
  is_personalizable: false,
  shipping_profile_id: null,
  return_policy_id:  null,
  tags
};

return [{ json: { etsy_shop_id: row.etsy_shop_id, access_token: row.access_token, listing_id: row.listing_id, payload } }];
